    public var clockExitTitle: String { pick("Landlord's defect notice", "Avis des défauts du bailleur", "Mängelrüge der Vermieterschaft", "Notifica dei difetti del locatore", "Notificaziun da mancanzas dal locatur") }
    public var clockExitBody: String { pick("Art. 267a CO requires the landlord to inspect on return and notify the tenant immediately of each defect for which liability is claimed. BGer 4A_388/2013 reports usual guidance of 2 to 3 working days, another view up to one week, and confirms that circumstances decide. Send an itemized notice without delay and keep proof of delivery.", "L'art. 267a CO impose au bailleur de vérifier la chose à sa restitution et d'aviser immédiatement le locataire de chaque défaut dont il entend le rendre responsable. L'arrêt TF 4A_388/2013 mentionne une pratique de 2 à 3 jours ouvrables, une autre opinion allant jusqu'à une semaine, et rappelle que les circonstances décident. Envoyez sans délai un avis détaillé et conservez la preuve d'envoi.", "Art. 267a OR verlangt, dass die Vermieterschaft bei der Rückgabe prüft und der Mieterschaft jeden Mangel, für den sie einstehen soll, sofort meldet. BGer 4A_388/2013 nennt als übliche Richtlinie 2 bis 3 Werktage, eine andere Auffassung bis zu einer Woche, und stellt auf die Umstände ab. Senden Sie unverzüglich eine detaillierte Mitteilung und bewahren Sie den Zustellnachweis auf.", "L'art. 267a CO impone al locatore di esaminare la cosa alla riconsegna e di notificare immediatamente al conduttore ogni difetto di cui intende renderlo responsabile. La sentenza TF 4A_388/2013 menziona una prassi di 2 o 3 giorni lavorativi, un'altra opinione fino a una settimana, e conferma che contano le circostanze. Inviate senza ritardo una notifica dettagliata e conservate la prova.", "L'art. 267a DO pretenda che il locatur examineschia l'object tar la restituziun e notifitgeschia immediat mintga mancanza imputada al locatari. La sentenzia TF 4A_388/2013 menziunescha 2 fin 3 dis da lavur sco pratica usitada, in'autra opiniun fin ad in'emna, e resguarda las circumstanzas. Tramettai senza retard ina glista detagliada e conservai la cumprova.") }
    public var clockEntryTitle: String { pick("Tenant's move-in list", "Liste d'entrée du locataire", "Mängelliste beim Einzug", "Lista dei difetti alla consegna", "Glista da mancanzas tar l'entrada") }
    public var clockEntryBody: String { pick("Check the lease and applicable cantonal terms. If they set a ten-day period for additions to the move-in record, meet it; otherwise report additional defects promptly in writing and keep proof. Ten days is not a uniform federal statutory deadline.", "Vérifiez le bail et les règles cantonales applicables. S'ils prévoient dix jours pour compléter l'état des lieux d'entrée, respectez ce délai ; sinon, signalez rapidement tout défaut supplémentaire par écrit et conservez la preuve. Dix jours ne constituent pas un délai légal fédéral uniforme.", "Mietvertrag und anwendbare kantonale Regeln prüfen. Sehen sie zehn Tage für Ergänzungen zum Einzugsprotokoll vor, ist diese Frist einzuhalten; andernfalls zusätzliche Mängel rasch schriftlich melden und den Nachweis aufbewahren. Zehn Tage sind keine einheitliche bundesrechtliche Frist.", "Verificate il contratto e le regole cantonali applicabili. Se prevedono dieci giorni per completare il verbale d'entrata, rispettate tale termine; altrimenti segnalate rapidamente per iscritto gli ulteriori difetti e conservate la prova. Dieci giorni non sono un termine legale federale uniforme.", "Controllai il contract e las reglas chantunalas applitgablas. Sch'ellas fixeschan diesch dis per cumplettar il protocol d'entrada, observai quel termin; uschiglio annunziai svelt en scrit ulteriuras mancanzas e conservai la cumprova. Diesch dis n'èn betg in termin federal unitar.") }
    public func tipRecord() -> Tip { Tip(lead: pick("This signature confirms the complete handover record and its reservations, without admitting liability or a payment obligation.", "Cette signature confirme l’ensemble du constat et ses réserves, sans reconnaissance de responsabilité ni de dette.", "Diese Unterschrift bestätigt das vollständige Protokoll samt Vorbehalten, ohne Anerkennung einer Haftung oder Zahlungspflicht.", "Questa firma conferma l’intero verbale e le riserve, senza riconoscimento di responsabilità o debito.", "Questa suttascripziun conferma l’entir protocol e las resalvas, senza renconuschientscha da responsabladad u da debit."), bullets: [pick("Responsibility and any amount are handled separately", "La responsabilité et tout montant sont traités séparément", "Verantwortung und ein allfälliger Betrag werden getrennt behandelt", "Responsabilità ed eventuali importi sono trattati separatamente", "Responsabladad ed eventuals imports vegnan tractads separadamain"), pick("Any reservation entered before signing is printed beside that person's outcome", "Toute réserve saisie avant la signature est imprimée à côté de l'issue de cette personne", "Ein vor der Unterschrift erfasster Vorbehalt steht neben dem Ergebnis dieser Person", "Ogni riserva inserita prima della firma è stampata accanto all'esito della persona", "Mintga resalva endatada avant la suttascripziun vegn stampada dasper il resultat da la persuna"), pick("It may be refused; a refusal is simply recorded", "Elle peut être refusée ; le refus est simplement consigné", "Sie darf verweigert werden; die Verweigerung wird schlicht protokolliert", "Può essere rifiutata; il rifiuto viene semplicemente verbalizzato", "Ella po vegnir refusada; la refusa vegn simplamain registrada")]) }
    public func tipDeposit() -> Tip { Tip(lead: pick("Two legitimate roads for the deposit:", "Deux voies légitimes pour la garantie :", "Zwei legitime Wege für das Depot:", "Due vie legittime per il deposito:", "Duas vias legitimas per il deposit:"), bullets: [pick("Blocked account: release follows Art. 257e CO, including agreement or an enforceable title", "Compte bloqué : la libération suit l'art. 257e CO, notamment l'accord ou un titre exécutoire", "Sperrkonto: Freigabe nach Art. 257e OR, insbesondere mit Zustimmung oder Vollstreckungstitel", "Conto bloccato: lo svincolo segue l'art. 257e CO, incluso l'accordo o un titolo esecutivo", "Conto bloccà: liberaziun tenor l'art. 257e DO, cun consentiment u in titel executabel"), pick("Guarantee insurance: compare the provider's current recurring premium and refund terms", "Assurance de garantie : comparez la prime périodique et les conditions de remboursement actuelles", "Kautionsversicherung: aktuelle wiederkehrende Prämie und Rückerstattungsbedingungen vergleichen", "Assicurazione di garanzia: confrontate il premio periodico e le condizioni di rimborso attuali", "Assicuranza da garanzia: cumparegliai la premia periodica e las cundiziuns actualas da restituziun"), pick("The exit protocol ends with the release step that matches", "L'état des lieux de sortie se termine par l'étape de libération correspondante", "Das Rückgabeprotokoll endet mit dem passenden Freigabeschritt", "Il verbale di riconsegna termina con il passo di svincolo corrispondente", "Il protocol da sortida finescha cun il pass da liberaziun correspundent")]) }
    public func tipCharged() -> Tip { Tip(lead: pick("An exit protocol is a valid defect notice only for the defects it explicitly charges to the tenant.", "L'état des lieux de sortie ne vaut avis des défauts que pour les défauts explicitement imputés au locataire.", "Das Rückgabeprotokoll gilt nur für die dem Mieter ausdrücklich angelasteten Mängel als Mängelrüge.", "Il verbale di riconsegna vale come notifica dei difetti solo per i difetti esplicitamente imputati al conduttore.", "Il protocol da sortida vala sco notificaziun mo per las mancanzas messas explicitamain a quint al locatari."), bullets: [pick("Unmarked findings document the state of the flat, without a claim", "Les constats non marqués documentent l'état, sans prétention", "Unmarkierte Befunde dokumentieren den Zustand, ohne Forderung", "I rilievi non marcati documentano lo stato, senza pretese", "Constataziuns betg marcadas documenteschan il stadi, senza pretensiun")]) }
    public func tipOneSided() -> Tip { Tip(lead: pick("Nobody on the other side of the threshold:", "Personne de l'autre côté du seuil :", "Niemand auf der anderen Seite der Schwelle:", "Nessuno dall'altra parte della soglia:", "Nagin da l'autra vart:"), bullets: [pick("Photograph everything, dated", "Tout photographier, avec date", "Alles fotografieren, datiert", "Fotografare tutto, con data", "Fotografar tut, cun data"), pick("A neutral witness signs the record", "Un témoin neutre signe le constat", "Eine neutrale Zeugin unterschreibt den Befund", "Un testimone neutrale firma il rilievo", "Ina perditga neutrala suttascriva il protocol"), pick("Return keys by an agreed, traceable method", "Rendre les clés par une méthode convenue et traçable", "Schlüssel auf vereinbarte, nachweisbare Weise zurückgeben", "Restituire le chiavi con un metodo concordato e tracciabile", "Restituir las clavs cun ina metoda cunvegnida e cumprovabla"), pick("Keep proof of the key delivery", "Conserver la preuve de remise des clés", "Nachweis der Schlüsselzustellung aufbewahren", "Conservare la prova di consegna delle chiavi", "Conservar la cumprova da consegna da las clavs")]) }
    public func tipZeitwert() -> Tip { Tip(lead: pick("The arithmetic of the joint MV and HEV lifespan table.", "L'arithmétique de la table paritaire ASLOCA/MV et HEV.", "Die Arithmetik der paritätischen Lebensdauertabelle von MV und HEV.", "L'aritmetica della tabella paritetica ASI e HEV.", "L'aritmetica da la tabella paritetica da MV ed HEV."), bullets: [pick("Lifespan estimates residual value; actual repair and loss still matter", "La longévité estime la valeur résiduelle ; la réparation et le dommage réels restent déterminants", "Die Lebensdauer schätzt den Restwert; tatsächliche Reparatur und Schaden bleiben massgebend", "La durata stima il valore residuo; riparazione e danno effettivi restano determinanti", "La durada stima la valur restanta; reparatura e donn effectiv restan decisivs"), pick("Normal wear is not charged to the tenant", "L'usure normale n'est pas imputée au locataire", "Normale Abnützung wird der Mieterschaft nicht belastet", "L'usura normale non è addebitata al conduttore", "L'isanza normala na vegn betg debitada al locatari"), pick("Use the known installation or renovation date", "Utilisez la date connue de pose ou de rénovation", "Bekanntes Einbau- oder Renovationsdatum verwenden", "Usate la data nota di installazione o ristrutturazione", "Duvrai la data enconuschenta da l'installaziun u renovaziun"), pick("Values here are public citations; the full table is sold by HEV and MV", "Valeurs publiques ; la table complète est vendue par HEV et ASLOCA", "Öffentliche Werte; die vollständige Tabelle verkaufen HEV und MV", "Valori pubblici; la tabella completa è venduta da HEV e ASI", "Valurs publicas; la tabella cumpletta vendan HEV e MV"), pick("Not legal advice; conciliation has no court fee, but your own costs may remain", "Pas un conseil juridique ; la conciliation est sans frais judiciaires, mais vos propres frais peuvent subsister", "Keine Rechtsberatung; im Schlichtungsverfahren fallen keine Gerichtskosten an, eigene Kosten können bleiben", "Non è consulenza legale; la conciliazione non comporta spese giudiziarie, ma possono restare costi propri", "Nagin cussegl giuridic; la mediaziun n'ha nagins custs giudizials, ma agens custs pon restar")]) }
    public func tipClocks() -> Tip { Tip(lead: pick("Practice values with their sources, not legal advice.", "Des valeurs de pratique avec leurs sources, pas un conseil juridique.", "Praxiswerte mit ihren Quellen, keine Rechtsberatung.", "Valori di pratica con le loro fonti, non consulenza legale.", "Valurs da pratica cun lur funtaunas, nagin cussegl giuridic."), bullets: [pick("Exit notice: Art. 267a CO and BGer 4A_388/2013", "Avis des défauts : art. 267a CO et TF 4A_388/2013", "Mängelrüge: Art. 267a OR und BGer 4A_388/2013", "Notifica dei difetti: art. 267a CO e TF 4A_388/2013", "Notificaziun: art. 267a DO e TF 4A_388/2013"), pick("Cantonal and local holidays are not calculated; check the calendar", "Les jours fériés cantonaux et locaux ne sont pas calculés ; vérifiez le calendrier", "Kantonale und lokale Feiertage werden nicht berechnet; Kalender prüfen", "Le festività cantonali e locali non sono calcolate; verificate il calendario", "Firaus chantunals e locals na vegnan betg calculads; controllai il chalender"), pick("Deposit: Art. 257e CO", "Garantie : art. 257e CO", "Depot: Art. 257e OR", "Deposito: art. 257e CO", "Deposit: art. 257e DO"), pick("No court fee is charged in conciliation proceedings; personal costs may remain", "La procédure de conciliation ne comporte pas de frais judiciaires ; des frais personnels peuvent subsister", "Im Schlichtungsverfahren werden keine Gerichtskosten erhoben; eigene Kosten können bleiben", "Nella procedura di conciliazione non sono riscosse spese giudiziarie; possono restare costi personali", "En la procedura da mediaziun na vegnan incassads nagins custs giudizials; agens custs pon restar")]) }
    public func tipShareNow() -> Tip { Tip(lead: pick("Send the PDF to both parties now, at the door.", "Envoyez le PDF aux deux parties maintenant, sur le pas de porte.", "Senden Sie das PDF beiden Parteien jetzt, an der Türe.", "Inviate il PDF a entrambe le parti adesso, sulla soglia.", "Trametti il PDF ad omaduas partidas ussa, sin la sava."), bullets: [pick("Prompt delivery to both creates clear proof of what each party received and when", "La remise rapide aux deux établit clairement ce que chaque partie a reçu et quand", "Rasche Zustellung an beide belegt klar, was jede Partei wann erhalten hat", "La consegna rapida a entrambi prova chiaramente cosa ha ricevuto ciascuna parte e quando", "La consegna svelta ad omadus cumprova cleramain tge che mintga partida ha survegnì e cura"), pick("Exit defects still require prompt, itemized and provable notice under Art. 267a CO", "Les défauts de sortie exigent toujours un avis rapide, détaillé et prouvable selon l'art. 267a CO", "Auszugsmängel verlangen weiterhin eine rasche, einzelne und nachweisbare Mitteilung nach Art. 267a OR", "I difetti di riconsegna richiedono sempre una notifica rapida, dettagliata e comprovabile secondo l'art. 267a CO", "Mancanzas da sortida pretendan vinavant ina notificaziun svelta, detagliada e cumprovabla tenor l'art. 267a DO"), pick("A drawn signature is an acknowledgement in this record, not a qualified electronic signature", "Une signature dessinée vaut reconnaissance dans ce constat, pas signature électronique qualifiée", "Eine gezeichnete Unterschrift ist eine Bestätigung in diesem Protokoll, keine qualifizierte elektronische Signatur", "Una firma disegnata è una conferma in questo verbale, non una firma elettronica qualificata", "Ina suttascripziun dissegnada è ina conferma en quest protocol, betg ina suttascripziun electronica qualifitgada")]) }
