    public func archiveSavedOpen(_ name: String) -> String { pick("Saved \(name) in Files, in the Limen app folder. Without a password: anyone with this file can read its records.", "Enregistré sous \(name) dans Fichiers, dans le dossier de l’app Limen. Sans mot de passe : toute personne détenant ce fichier peut lire ses constats.", "Als \(name) in Dateien im Ordner der App Limen gespeichert. Ohne Passwort: Wer diese Datei hat, kann die Protokolle darin lesen.", "Salvato come \(name) in File, nella cartella dell’app Limen. Senza password: chiunque abbia questo file può leggere i verbali.", "Memorisà sco \(name) en Datotecas, en l’ordinatur da l’app Limen. Senza pled-clav: mintgin che ha questa datoteca po leger ils protocols.") }
    public func archiveRestored(_ result: ArchiveImportResult) -> String { pick("Restored \(result.imported); kept \(result.skippedExisting) existing; rejected \(result.rejected) invalid.", "Restaurés : \(result.imported) ; existants conservés : \(result.skippedExisting) ; invalides refusés : \(result.rejected).", "Wiederhergestellt: \(result.imported); bestehend belassen: \(result.skippedExisting); ungültig abgelehnt: \(result.rejected).", "Ripristinati: \(result.imported); esistenti mantenuti: \(result.skippedExisting); non validi rifiutati: \(result.rejected).", "Restaurads: \(result.imported); existents mantegnids: \(result.skippedExisting); nunvalids refusads: \(result.rejected).") }
